TRUE, simulate = function (object, nsim) 
{
    ftd <- fitted(object)
    n <- length(ftd)
    ntot <- n * nsim
    wts <- object$prior.weights
    if (any(wts%%1 != 0)) 
        stop("cannot simulate from non-integer prior.weights")
    if (!is.null(m <- object$model)) {
        y <- model.response(m)
        if (is.factor(y)) {
